/**
 * Per-frame telemetry, with the provenance of every value shown next to it.
 *
 * The provenance column is the point of this panel. "EAR 0.26" is a completely
 * different claim depending on whether it was measured from this frame, estimated
 * by a fallback, or generated by the demo generator. Hiding that distinction is how
 * a research prototype starts lying, so the badge is mandatory here, not decoration.
 */
import { Badge, MetricRow, Panel } from './primitives';
import { NO_VALUE, formatAu, formatLatency, formatNumber, formatPercent } from '../lib/format';
import { SIGNAL_STATUS_LABELS, asSignalStatus, type Telemetry } from '../types';

export interface TelemetryPanelProps {
  telemetry: Telemetry | null;
}

function statusBadge(status: ReturnType<typeof asSignalStatus>) {
  const label = SIGNAL_STATUS_LABELS[status];
  switch (status) {
    case 'live':
      return <Badge tone="live">{label}</Badge>;
    case 'synthetic':
      return <Badge tone="synthetic" title="Generated by the deterministic demo generator — not a measurement">{label}</Badge>;
    case 'estimated':
      return <Badge tone="warn" title="Produced by a fallback heuristic, not a measurement">{label}</Badge>;
    case 'not_detected':
      return <Badge tone="warn">{label}</Badge>;
    default:
      return <Badge tone="neutral">{label}</Badge>;
  }
}

function sourceOf(telemetry: Telemetry | null, key: string) {
  return asSignalStatus(telemetry?.signal_status?.[key]);
}

export function TelemetryPanel({ telemetry }: TelemetryPanelProps) {
  const probs = telemetry?.class_probs ?? {};
  const entries = Object.entries(probs);
  const au = telemetry?.au ?? {};
  const auIntensities = telemetry?.au_intensities ?? {};
  const active = telemetry?.active_aus ?? {};
  const auCodes = Object.keys(au);

  return (
    <Panel
      title="Telemetry"
      aside={
        telemetry ? (
          <Badge tone={telemetry.mode === 'onnx' ? 'live' : 'synthetic'}>
            {telemetry.mode ?? 'mode unknown'}
          </Badge>
        ) : (
          <Badge tone="neutral">no data</Badge>
        )
      }
    >
      {!telemetry ? (
        <p className="text-sm text-slate-400">
          No telemetry has arrived yet. Nothing is shown rather than showing placeholder
          numbers.
        </p>
      ) : (
        <>
          <dl className="text-sm">
            <MetricRow
              label="Fatigue probability"
              value={
                typeof telemetry.p_fatigue === 'number' ? formatPercent(telemetry.p_fatigue, 1) : NO_VALUE
              }
              source={statusBadge(sourceOf(telemetry, 'class_probs'))}
            />
            <MetricRow
              label="Eye aspect ratio"
              value={typeof telemetry.ear === 'number' ? formatNumber(telemetry.ear, 3) : NO_VALUE}
              source={statusBadge(sourceOf(telemetry, 'ear'))}
            />
            <MetricRow
              label="Heart rate (rPPG)"
              value={typeof telemetry.rppg_bpm === 'number' ? `${telemetry.rppg_bpm.toFixed(0)} bpm` : NO_VALUE}
              source={statusBadge(sourceOf(telemetry, 'rppg_bpm'))}
            />
            <MetricRow
              label="Face detected"
              value={telemetry.face_detected ? 'yes' : 'no'}
              source={statusBadge(sourceOf(telemetry, 'face_detection'))}
              tone={telemetry.face_detected ? 'live' : 'warn'}
            />
            <MetricRow
              label="Illumination"
              value={
                typeof telemetry.illumination === 'number'
                  ? formatPercent(telemetry.illumination, 0)
                  : NO_VALUE
              }
            />
            <MetricRow
              label="Inference latency"
              value={formatLatency(telemetry.inference_latency_ms)}
            />
            <MetricRow label="Frame timestamp" value={formatNumber(telemetry.ts, 3)} source="epoch s" />
          </dl>

          <div className="mt-4">
            <h3 className="metric-label mb-2">Class probabilities</h3>
            <dl className="text-sm">
              {entries.length === 0 ? (
                <p className="text-sm text-slate-500">Not reported.</p>
              ) : (
                entries.map(([label, value]) => (
                  <MetricRow
                    key={label}
                    label={label}
                    value={formatPercent(value, 1)}
                    source={statusBadge(sourceOf(telemetry, 'class_probs'))}
                  />
                ))
              )}
            </dl>
          </div>

          <div className="mt-4">
            <h3 className="metric-label mb-2">
              Facial action units <span className="normal-case">(FACS intensity 0-5)</span>
            </h3>
            {auCodes.length === 0 ? (
              <p className="text-sm text-slate-400">
                A face Action-Unit regressor is not part of this deployment, so no AU
                intensities are reported.{' '}
                {sourceOf(telemetry, 'au') === 'not_configured'
                  ? 'Status: not configured.'
                  : `Status: ${SIGNAL_STATUS_LABELS[sourceOf(telemetry, 'au')]}.`}
              </p>
            ) : (
              <ul className="space-y-2">
                {auCodes.map((code) => {
                  const intensity = au[code];
                  const normalised = auIntensities[code];
                  const isActive = active[code] === true;
                  const percent = typeof normalised === 'number' ? Math.round(normalised * 100) : 0;
                  return (
                    <li key={code}>
                      <div className="flex items-baseline justify-between text-sm">
                        <span className="font-mono text-slate-300">{code}</span>
                        <span className="flex items-center gap-2">
                          <span className="metric-value">{formatAu(intensity)}</span>
                          {isActive ? <Badge tone="warn">active</Badge> : null}
                          {sourceBadgeOrNull(telemetry, 'au')}
                        </span>
                      </div>
                      <div
                        className="mt-1 h-1.5 overflow-hidden rounded bg-slate-800"
                        role="img"
                        aria-label={`${code} at ${percent} percent of the FACS scale`}
                      >
                        <div
                          className="h-full bg-sky-400"
                          style={{ width: `${Math.min(100, Math.max(0, percent))}%` }}
                        />
                      </div>
                    </li>
                  );
                })}
              </ul>
            )}
          </div>
        </>
      )}
    </Panel>
  );
}

function sourceBadgeOrNull(telemetry: Telemetry, key: string) {
  const status = sourceOf(telemetry, key);
  return status === 'unknown' ? null : statusBadge(status);
}
